\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc}
\pagestyle{empty}

% ══ DARK BLOOMBERG PALETTE ══
\definecolor{darkbg}{HTML}{0B1120}
\definecolor{cardbg}{HTML}{131B2E}
\definecolor{cardheader}{HTML}{19243B}
\definecolor{nvgold}{HTML}{F5A623}
\definecolor{elecblue}{HTML}{3B82F6}
\definecolor{brightblue}{HTML}{60A5FA}
\definecolor{mutedblue}{HTML}{1D4ED8}
\definecolor{deepblue}{HTML}{1E3A5F}
\definecolor{lighttext}{HTML}{F1F5F9}
\definecolor{graytext}{HTML}{94A3B8}
\definecolor{dimtext}{HTML}{64748B}
\definecolor{gridline}{HTML}{1A2540}
\definecolor{statbg}{HTML}{0F1829}
\definecolor{accentgreen}{HTML}{10B981}
\definecolor{accentred}{HTML}{EF4444}
\definecolor{accpurple}{HTML}{A78BFA}
\definecolor{accorange}{HTML}{F97316}
\definecolor{titlebar}{HTML}{080D1A}
\definecolor{divider}{HTML}{1E3A5F}
\definecolor{footerbg}{HTML}{0A1020}
\definecolor{goldbg}{HTML}{1A1508}
\definecolor{statborder}{HTML}{1E3050}

\pagecolor{darkbg}
\color{lighttext}

% ══ CARD STYLES (dark theme) ══
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{elecblue},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{elecblue},
    coltitle=elecblue, colbacktitle=cardheader,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={deepblue},
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{nvgold},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{nvgold},
    coltitle=nvgold, colbacktitle=cardheader,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={nvgold!30!darkbg},
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
  greencard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{accentgreen},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentgreen},
    coltitle=accentgreen, colbacktitle=cardheader,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={accentgreen!30!darkbg},
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=deepblue!60!darkbg,
    borderline west={5pt}{0pt}{brightblue},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=deepblue,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.3, shadow xshift=2mm, shadow yshift=-2mm},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════
% TITLE BAR: top to row3
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=titlebar, colframe=titlebar, colupper=white,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=14pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{nvgold!60!darkbg},
]{name=title, column=1, span=3, between=top and row3}{%
  {\fontsize{28}{34}\selectfont\color{nvgold}\bfseries GLOBAL MARKET INTELLIGENCE \,|\, MID-2025}\\[16pt]
  {\fontsize{80}{96}\selectfont\bfseries\color{white} The World's Most Valuable}\\[6pt]
  {\fontsize{80}{96}\selectfont\bfseries\color{white} Companies in 2025}\\[14pt]
  {\fontsize{30}{36}\selectfont\color{graytext}%
   A comparative snapshot of the top publicly traded companies by market capitalization}%
}

% ══════════════════════════════════════════════
% STAT BANNER: row3 to row5
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={2pt}{0pt}{deepblue},
]{name=stats, column=1, span=3, between=row3 and row5}{%
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \begin{tcolorbox}[enhanced, colback=goldbg, boxrule=1pt, colframe=nvgold!40!darkbg,
      arc=3pt, left=6pt, right=6pt, top=10pt, bottom=10pt, halign=center]
      {\fontsize{68}{82}\selectfont\bfseries\color{nvgold} \$4.82T}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{graytext} NVIDIA \(\cdot\) Rank \#1}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \begin{tcolorbox}[enhanced, colback=cardbg, boxrule=1pt, colframe=statborder,
      arc=3pt, left=6pt, right=6pt, top=10pt, bottom=10pt, halign=center]
      {\fontsize{68}{82}\selectfont\bfseries\color{elecblue} 10,796}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{graytext} Companies Tracked}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \begin{tcolorbox}[enhanced, colback=cardbg, boxrule=1pt, colframe=statborder,
      arc=3pt, left=6pt, right=6pt, top=10pt, bottom=10pt, halign=center]
      {\fontsize{68}{82}\selectfont\bfseries\color{elecblue} \$142.9T}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{graytext} Total Global Market Cap}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \begin{tcolorbox}[enhanced, colback=cardbg, boxrule=1pt, colframe=statborder,
      arc=3pt, left=6pt, right=6pt, top=10pt, bottom=10pt, halign=center]
      {\fontsize{68}{82}\selectfont\bfseries\color{nvgold} 11}\\[6pt]
      {\fontsize{24}{30}\selectfont\color{graytext} Trillion-Dollar Companies}
    \end{tcolorbox}
  \end{minipage}%
}

% ══════════════════════════════════════════════
% TRILLION-DOLLAR CLUB (CENTERPIECE): row5 to row14
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=darkbg, boxrule=0pt, arc=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  borderline south={2pt}{0pt}{deepblue},
]{name=chart, column=1, span=3, between=row5 and row14}{%
  \centering
  {\fontsize{44}{52}\selectfont\bfseries\color{nvgold} THE TRILLION-DOLLAR CLUB}\\[4pt]
  {\fontsize{26}{32}\selectfont\color{graytext} 11 companies exceeding \$1 trillion market capitalization \,|\, Top 5 alone: \$18.5T (13\% of all tracked value)}\\[18pt]
  %
  \begin{tikzpicture}[x=1mm, y=-1mm]
    % Grid reference lines
    \foreach \t in {1,2,3,4} {
      \pgfmathsetmacro{\gx}{\t/4.82*480}
      \draw[gridline, line width=0.4mm] (\gx, -5) -- (\gx, 415);
      \node[above, text=dimtext, font=\fontsize{22}{26}\selectfont] at (\gx, -7) {\$\t T};
    }
    %
    % === TOP 5 (bright bars) ===
    % 1. NVIDIA (GOLD - dominant)
    \fill[nvgold, rounded corners=1.5mm] (0, 0) rectangle (480, 28);
    \node[anchor=east, text=lighttext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 14) {1};
    \node[anchor=east, text=white, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 14) {NVIDIA};
    \node[anchor=west, text=nvgold, font=\fontsize{28}{34}\selectfont\bfseries] at (488, 14) {\$4.82T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 14) {USA};
    %
    % 2. Alphabet
    \fill[elecblue, rounded corners=1.5mm] (0, 38) rectangle (401, 66);
    \node[anchor=east, text=lighttext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 52) {2};
    \node[anchor=east, text=white, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 52) {Alphabet (Google)};
    \node[anchor=west, text=brightblue, font=\fontsize{28}{34}\selectfont\bfseries] at (409, 52) {\$4.03T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 52) {USA};
    %
    % 3. Apple
    \fill[elecblue, rounded corners=1.5mm] (0, 76) rectangle (386, 104);
    \node[anchor=east, text=lighttext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 90) {3};
    \node[anchor=east, text=white, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 90) {Apple};
    \node[anchor=west, text=brightblue, font=\fontsize{28}{34}\selectfont\bfseries] at (394, 90) {\$3.87T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 90) {USA};
    %
    % 4. Microsoft
    \fill[elecblue, rounded corners=1.5mm] (0, 114) rectangle (311, 142);
    \node[anchor=east, text=lighttext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 128) {4};
    \node[anchor=east, text=white, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 128) {Microsoft};
    \node[anchor=west, text=brightblue, font=\fontsize{28}{34}\selectfont\bfseries] at (319, 128) {\$3.12T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 128) {USA};
    %
    % 5. Amazon
    \fill[elecblue, rounded corners=1.5mm] (0, 152) rectangle (268, 180);
    \node[anchor=east, text=lighttext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 166) {5};
    \node[anchor=east, text=white, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 166) {Amazon};
    \node[anchor=west, text=brightblue, font=\fontsize{28}{34}\selectfont\bfseries] at (276, 166) {\$2.69T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 166) {USA};
    %
    % --- DIVIDER LINE between top 5 and rest ---
    \draw[nvgold!50!darkbg, line width=1.2mm, dashed] (-180, 190) -- (590, 190);
    \node[text=nvgold!70, font=\fontsize{20}{24}\selectfont\itshape, anchor=east] at (590, 198) {Top 5: \$18.5T combined (13\% of global value)};
    %
    % === REMAINING 6 (muted bars) ===
    % 6. Broadcom
    \fill[mutedblue, rounded corners=1.5mm] (0, 210) rectangle (188, 238);
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 224) {6};
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 224) {Broadcom};
    \node[anchor=west, text=graytext, font=\fontsize{26}{32}\selectfont\bfseries] at (196, 224) {\$1.89T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 224) {USA};
    %
    % 7. TSMC
    \fill[mutedblue, rounded corners=1.5mm] (0, 248) rectangle (187, 276);
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 262) {7};
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 262) {TSMC};
    \node[anchor=west, text=graytext, font=\fontsize{26}{32}\selectfont\bfseries] at (195, 262) {\$1.88T};
    \node[anchor=west, text=accentgreen, font=\fontsize{20}{24}\selectfont] at (555, 262) {Taiwan};
    %
    % 8. Saudi Aramco
    \fill[mutedblue, rounded corners=1.5mm] (0, 286) rectangle (176, 314);
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 300) {8};
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 300) {Saudi Aramco};
    \node[anchor=west, text=graytext, font=\fontsize{26}{32}\selectfont\bfseries] at (184, 300) {\$1.77T};
    \node[anchor=west, text=accorange, font=\fontsize{20}{24}\selectfont] at (555, 300) {Saudi Arabia};
    %
    % 9. Meta
    \fill[mutedblue, rounded corners=1.5mm] (0, 324) rectangle (170, 352);
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 338) {9};
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 338) {Meta Platforms};
    \node[anchor=west, text=graytext, font=\fontsize{26}{32}\selectfont\bfseries] at (178, 338) {\$1.71T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 338) {USA};
    %
    % 10. Tesla
    \fill[mutedblue, rounded corners=1.5mm] (0, 362) rectangle (146, 390);
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 376) {10};
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 376) {Tesla};
    \node[anchor=west, text=graytext, font=\fontsize{26}{32}\selectfont\bfseries] at (154, 376) {\$1.46T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 376) {USA};
    %
    % 11. Berkshire Hathaway
    \fill[mutedblue, rounded corners=1.5mm] (0, 400) rectangle (102, 428);
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-8, 414) {11};
    \node[anchor=east, text=graytext, font=\fontsize{28}{34}\selectfont\bfseries] at (-20, 414) {Berkshire Hathaway};
    \node[anchor=west, text=graytext, font=\fontsize{26}{32}\selectfont\bfseries] at (110, 414) {\$1.02T};
    \node[anchor=west, text=dimtext, font=\fontsize{20}{24}\selectfont] at (555, 414) {USA};
  \end{tikzpicture}%
}

% ══════════════════════════════════════════════
% COUNTRY DOMINANCE: row14 to row17, col 1
% ══════════════════════════════════════════════
\posterbox[goldcard, title={Country Dominance}
]{name=country, column=1, between=row14 and row17}{%
  \fontsize{30}{40}\selectfont
  \vspace{4pt}
  {\fontsize{56}{66}\selectfont\bfseries\color{nvgold} 15}\,{\fontsize{30}{36}\selectfont\color{graytext} of 20}\quad{\fontsize{30}{36}\selectfont\color{lighttext} are American}\\[16pt]
  %
  % Grid visualization: 20 squares, 15 blue (USA)
  \begin{tikzpicture}[x=1mm, y=-1mm]
    % Row 1 (5 squares)
